# Generated by governance model version 3. Only the generator changes this file.
"""The governance gate: the required check `governance-gate` on every PR into the default branch.

The workflow `.github/workflows/governance-gate.yml` runs this script from the default
branch's checkout. It reads the PR's metadata from the event and the PR head's git objects,
and never checks out or runs the PR's tree. The default branch's record judges, so a PR
can't change how it is judged.

The checks, in order; each failure is one plain English line naming the fix:

1. Author: the repository owner or the record's agent account.
2. Risk line: exactly one `Risk: <low|medium|high> — <reason>` line.
3. Pure revert: a `Reverts:` line names a full commit SHA on the default branch. That
   commit's revert, recomputed on the PR's merge-base, equal to the head's tree is a pure
   revert: any tier passes, and step 4 is skipped.
4. Floors: the declared tier reaches the highest floor among the sensitive paths that the
   PR's changed paths match, deletions and both sides of a rename included.

Every rule runs and reports. Floors run only when the risk line gives a tier and no pure
revert is confirmed. A default branch whose record is missing or doesn't parse, or git
objects that can't be read, fail the gate with one line, since it can't judge without them.

This file also holds the governed repository's one parser for the record and for the PR
body's `Risk:` and `Reverts:` lines. Scripts beside it import it as the module `gate`:
`parse_record`, `parse_body`, `matches` and `verdict`, below.

The record is a strict YAML subset: block mappings and sequences, plain or double-quoted
scalars, and `#` comments, in UTF-8 with LF line endings. Its keys come in this order:
`version`, a positive integer written plain; `agent_account`; `sensitive_paths`; then
`confirmed`, holding `sensitive_paths` and `required_checks` and, from version 3, optionally
`review_bots`: the enabled review bots in preference order, each `codex` or `copilot`, none
twice. Each sensitive path is a `pattern`, kept as written, with a `floor` of `medium` or
`high`. A list key with no items is an empty list. Anything else doesn't parse. Text that
YAML could read as null, a boolean or a number is double-quoted.

A pattern is root-relative and case-sensitive. A segment that is exactly `**` matches any
number of segments, none included; any other `*` matches within one segment, so a segment
`a**b` reads as `a*b`. Nothing else is special.

Python 3's standard library at the 3.9 level, plus `git` 2.40 or later, for
`merge-tree --merge-base`, and `gh`.
"""

import argparse
import json
import os
import re
import subprocess
import sys

# The record: the governed repository's side of #44 §5's one parser per side.

FLOORS = ("medium", "high")

# What a record never holds: every control character but LF, the line and paragraph
# separators, a byte order mark, the two noncharacters outside YAML's printable set, and
# surrogates. Text holds no LF either.
_NEVER = "\x00-\x09\x0b-\x1f\x7f-\x9f\u2028\u2029\ufeff\ufffe\uffff\ud800-\udfff"
_FORBIDDEN = re.compile("[%s]" % _NEVER)
_FORBIDDEN_IN_TEXT = re.compile("[\n%s]" % _NEVER)
_INDICATORS = ",[]{}#&*!|>'%@`"
# Plain scalars that aren't text: the YAML 1.1 and 1.2 null and boolean words, and anything
# starting like a number (a date included), which also refuses some text, such as `2fa/**`,
# that YAML would read as a string. Such text is double-quoted.
_NOT_TEXT = re.compile(
    r"(?:~|null|Null|NULL|true|True|TRUE|false|False|FALSE|yes|Yes|YES|no|No|NO|on|On|ON|off|Off|OFF|y|Y|n|N"
    r"|[-+]?\.?[0-9].*|[-+]?\.(?:inf|Inf|INF)|\.(?:nan|NaN|NAN))"
)
_VERSION = re.compile(r"[1-9][0-9]*")

RECORD_KEYS = ("version", "agent_account", "sensitive_paths", "confirmed")
CONFIRMED_KEYS = ("sensitive_paths", "required_checks")
# From version 3 the confirmed part also lists the enabled review bots, in preference order.
REVIEW_BOTS_VERSION = 3
CONFIRMED_KEYS_V3 = CONFIRMED_KEYS + ("review_bots",)
REVIEW_BOTS = ("codex", "copilot")
PATH_KEYS = ("pattern", "floor")


class RecordError(ValueError):
    """The record doesn't parse; the message names the line and what is wrong."""


def is_text(value):
    """Whether value can be a record's text: a non-empty string on one line, with no control character."""
    return isinstance(value, str) and bool(value) and not _FORBIDDEN_IN_TEXT.search(value)


class _Scalar(object):
    def __init__(self, text, quoted, line):
        self.text, self.quoted, self.line = text, quoted, line


class _Mapping(object):
    def __init__(self, line):
        self.line, self.entries = line, []


class _Sequence(object):
    def __init__(self, line):
        self.line, self.items = line, []


def _fail(line, message):
    raise RecordError("line %d %s" % (line, message))


def _quoted(content, line):
    """A double-quoted scalar at the start of content: (its text, the rest of content)."""
    out, index = [], 1
    while index < len(content):
        char = content[index]
        if char == '"':
            return "".join(out), content[index + 1:]
        if char == "\\":
            escaped = content[index + 1:index + 2]
            if escaped not in ('"', "\\"):
                _fail(line, 'has the escape \\%s; a double-quoted scalar escapes only \\" and \\\\' % escaped)
            out.append(escaped)
            index += 2
            continue
        out.append(char)
        index += 1
    _fail(line, "has a double-quoted scalar that doesn't close on its line")


def _plain(text, line):
    """Check a plain scalar's text."""
    if not text:
        _fail(line, "has an empty plain scalar")
    first, second = text[0], text[1:2]
    if first in _INDICATORS or first == '"' or (first in "-?:" and second in ("", " ")):
        _fail(line, "has a plain scalar starting with the indicator %r, which the record's subset doesn't allow" % first)
    if text.endswith(":"):
        _fail(line, "has a plain scalar ending with `:`")
    return _Scalar(text, False, line)


def _after_scalar(rest, line):
    """What may follow a scalar on its line: nothing, or a comment after a space."""
    stripped = rest.lstrip(" ")
    if stripped and not (stripped.startswith("#") and stripped != rest):
        _fail(line, "has %r after a scalar" % rest)


def _value(text, line):
    """A scalar value on a key's or an item's line."""
    if text.startswith('"'):
        value, rest = _quoted(text, line)
        _after_scalar(rest, line)
        return _Scalar(value, True, line)
    comment = text.find(" #")
    if comment >= 0:
        text = text[:comment]
    text = text.rstrip(" ")
    if ": " in text:
        _fail(line, "has a mapping inside a value, which the record's subset doesn't allow")
    return _plain(text, line)


def _split(content, line):
    """A line's content as ("item", rest), ("entry", key, value text) or ("scalar", scalar)."""
    if content == "-" or content.startswith("- "):
        return ("item", content[1:])
    if content.startswith('"'):
        key, rest = _quoted(content, line)
        stripped = rest.lstrip(" ")
        if stripped == ":" or stripped.startswith(": "):
            return ("entry", _Scalar(key, True, line), stripped[1:])
        _after_scalar(rest, line)
        return ("scalar", _Scalar(key, True, line))
    index = 0
    while index < len(content):
        if content[index] == ":" and content[index + 1:index + 2] in ("", " "):
            return ("entry", _plain(content[:index].rstrip(" "), line), content[index + 1:])
        if content[index] == "#" and index > 0 and content[index - 1] == " ":
            break
        index += 1
    return ("scalar", _value(content, line))


def _node_lines(text):
    """[line number, indentation, content] for every line that isn't blank or a comment."""
    nodes = []
    for number, raw in enumerate(text.split("\n"), 1):
        line = raw.rstrip(" ")
        content = line.lstrip(" ")
        if content and not content.startswith("#"):
            nodes.append([number, len(line) - len(content), content])
    return nodes


def _node(nodes, index):
    """The node starting at nodes[index], at that line's indentation: (node, next index)."""
    number, indent, content = nodes[index]
    form = _split(content, number)
    if form[0] == "item":
        return _sequence(nodes, index, indent)
    if form[0] == "entry":
        return _mapping(nodes, index, indent)
    return form[1], index + 1


def _nested(nodes, index, indent, compact):
    """The block a key or an item with no inline value holds, or None when it holds nothing.

    A key's block may also be a sequence at the key's own indentation (compact).
    """
    if index < len(nodes) and nodes[index][1] > indent:
        return _node(nodes, index)
    if compact and index < len(nodes) and nodes[index][1] == indent:
        if _split(nodes[index][2], nodes[index][0])[0] == "item":
            return _sequence(nodes, index, indent)
    return None, index


def _mapping(nodes, index, indent):
    mapping = _Mapping(nodes[index][0])
    while index < len(nodes) and nodes[index][1] >= indent:
        number, here, content = nodes[index]
        if here > indent:
            _fail(number, "is indented more than the mapping it sits in")
        form = _split(content, number)
        if form[0] != "entry":
            _fail(number, "is not a `key: value` entry of the mapping it sits in")
        key, rest = form[1], form[2].lstrip(" ")
        if any(existing.text == key.text for existing, _ in mapping.entries):
            _fail(number, "repeats the key %s" % key.text)
        if rest and not rest.startswith("#"):
            value, index = _value(rest, number), index + 1
        else:
            value, index = _nested(nodes, index + 1, indent, compact=True)
        mapping.entries.append((key, value))
    return mapping, index


def _sequence(nodes, index, indent):
    sequence = _Sequence(nodes[index][0])
    while index < len(nodes) and nodes[index][1] >= indent:
        number, here, content = nodes[index]
        if here > indent:
            _fail(number, "is indented more than the sequence it sits in")
        form = _split(content, number)
        if form[0] != "item":
            break
        rest = form[1]
        inline = rest.lstrip(" ")
        if not inline or inline.startswith("#"):
            item, index = _nested(nodes, index + 1, indent, compact=False)
        else:
            nodes[index] = [number, here + len(rest) - len(inline) + 1, inline]
            item, index = _node(nodes, index)
        sequence.items.append(item)
    return sequence, index


def _tree(text):
    nodes = _node_lines(text)
    if not nodes:
        raise RecordError("the record is empty")
    root, index = _node(nodes, 0)
    if index < len(nodes):
        _fail(nodes[index][0], "is outside the record's top-level mapping")
    return root


def _keys(node, keys, what, line):
    """A mapping's values by key, as (value, line), once its keys are exactly keys in order."""
    if not isinstance(node, _Mapping):
        _fail(getattr(node, "line", line), "must hold %s as a mapping of %s" % (what, ", ".join(keys)))
    found = tuple(key.text for key, _ in node.entries)
    if found != keys:
        unknown = [key for key in found if key not in keys]
        missing = [key for key in keys if key not in found]
        if unknown:
            problem = "the unknown key %s" % ", ".join(unknown)
        elif missing:
            problem = "no key %s" % ", ".join(missing)
        else:
            problem = "its keys out of order"
        _fail(node.line, "starts %s, which has %s; it holds %s, in that order" % (what, problem, ", ".join(keys)))
    return dict((key.text, (value, key.line)) for key, value in node.entries)


def _text(value, line, what):
    if not isinstance(value, _Scalar):
        _fail(line, "must give %s as text" % what)
    if not value.quoted and _NOT_TEXT.fullmatch(value.text):
        _fail(value.line, "gives %s as %r, which YAML can read as other than text; double-quote it" % (what, value.text))
    if not is_text(value.text):
        _fail(value.line, "gives %s as empty text or text with a control character" % what)
    return value.text


def _list(value, line, what, item):
    if value is None:
        return []
    if not isinstance(value, _Sequence):
        _fail(line, "must give %s as a block sequence" % what)
    return [item(element, line) for element in value.items]


def _sensitive_path(node, line):
    entries = _keys(node, PATH_KEYS, "a sensitive path", line)
    pattern = _text(*entries["pattern"], what="a pattern")
    floor = _text(*entries["floor"], what="a floor")
    if floor not in FLOORS:
        _fail(entries["floor"][1], "gives the floor %r; a floor is medium or high" % floor)
    return {"pattern": pattern, "floor": floor}


def _required_check(node, line):
    return _text(node, getattr(node, "line", line), "a required check")


def _review_bot(node, line):
    bot = _text(node, getattr(node, "line", line), "a review bot")
    if bot not in REVIEW_BOTS:
        _fail(getattr(node, "line", line), "names the review bot %r; a review bot is one of %s" % (bot, ", ".join(REVIEW_BOTS)))
    return bot


def _confirmed_keys(version, node):
    """The keys a record's confirmed part holds, in order: review_bots last, from version 3, when listed."""
    if version >= REVIEW_BOTS_VERSION and isinstance(node, _Mapping) and any(key.text == "review_bots" for key, _ in node.entries):
        return CONFIRMED_KEYS_V3
    return CONFIRMED_KEYS


def parse_record(data):
    """The record in data's bytes, or RecordError when it doesn't parse."""
    try:
        text = data.decode("utf-8")
    except UnicodeDecodeError:
        raise RecordError("the record is not UTF-8")
    forbidden = _FORBIDDEN.search(text)
    if forbidden:
        _fail(text.count("\n", 0, forbidden.start()) + 1, "holds the character U+%04X" % ord(forbidden.group()))

    entries = _keys(_tree(text), RECORD_KEYS, "the record", 1)
    version, line = entries["version"]
    if not isinstance(version, _Scalar) or version.quoted or not _VERSION.fullmatch(version.text):
        _fail(line, "must give version as a positive integer, written plain")
    number = int(version.text)
    node, line = entries["confirmed"]
    confirmed = _keys(node, _confirmed_keys(number, node), "confirmed", line)
    parsed = {
        "version": number,
        "agent_account": _text(*entries["agent_account"], what="agent_account"),
        "sensitive_paths": _list(*entries["sensitive_paths"], what="sensitive_paths", item=_sensitive_path),
        "confirmed": {
            "sensitive_paths": _list(*confirmed["sensitive_paths"], what="confirmed sensitive_paths", item=_sensitive_path),
            "required_checks": _list(*confirmed["required_checks"], what="required_checks", item=_required_check),
        },
    }
    if "review_bots" in confirmed:
        bots = _list(*confirmed["review_bots"], what="review_bots", item=_review_bot)
        if len(set(bots)) != len(bots):
            _fail(confirmed["review_bots"][1], "lists a review bot twice")
        parsed["confirmed"]["review_bots"] = bots
    return parsed


# The PR body's `Risk:` and `Reverts:` lines. Only lines that start with `Risk:` or `Reverts:`
# count, wherever they sit, and a CR before LF is dropped. The separator is an em dash with
# one space each side; a `Reverts:` value is 40 lowercase hexadecimal digits.

TIERS = ("low", "medium", "high")

# The separator is U+2014, the em dash; a hyphen or an en dash is malformed.
_RISK = re.compile("Risk: (%s) \u2014 (.*)" % "|".join(TIERS))
_REVERTS = re.compile(r"Reverts: ([0-9a-f]{40})[ \t]*")


def _risk(lines):
    if not lines:
        return "missing"
    if len(lines) > 1:
        return "more than one"
    match = _RISK.fullmatch(lines[0])
    reason = match.group(2).strip(" \t") if match else ""
    if not reason:
        return "malformed"
    return {"tier": match.group(1), "reason": reason}


def _reverts(lines):
    if not lines:
        return None
    if len(lines) > 1:
        return "more than one"
    match = _REVERTS.fullmatch(lines[0])
    return {"sha": match.group(1)} if match else "malformed"


def parse_body(body):
    """The body's risk and reverts.

    `risk` is {"tier", "reason"}, or "missing", "more than one" or "malformed". `reverts` is
    None when no line names one, {"sha"}, or "more than one" or "malformed".
    """
    lines = [line[:-1] if line.endswith("\r") else line for line in body.split("\n")]
    return {
        "risk": _risk([line for line in lines if line.startswith("Risk:")]),
        "reverts": _reverts([line for line in lines if line.startswith("Reverts:")]),
    }


# The gate.

CHECK = "governance-gate"
RECORD = ".github/governance/record.yml"
RANK = {"low": 0, "medium": 1, "high": 2}
# Paths named in a failure line, before "and N more".
SHOWN = 5


class GitError(Exception):
    """Git couldn't give the objects the gate judges."""


def _git(repo, args, codes=(0,)):
    """(exit code, stdout bytes) of a git command in repo; GitError on any other exit code."""
    result = subprocess.run(
        ["git", "-C", repo] + list(args), stdout=subprocess.PIPE, stderr=subprocess.PIPE
    )
    if result.returncode not in codes:
        stderr = " ".join(result.stderr.decode("utf-8", "replace").split())
        raise GitError("`git %s` failed: %s" % (" ".join(args), stderr))
    return result.returncode, result.stdout


def _line(repo, args):
    return _git(repo, args)[1].decode("utf-8").strip()


def _is_commit(repo, sha):
    return _git(repo, ["cat-file", "-e", sha + "^{commit}"], codes=(0, 1, 128))[0] == 0


def _segment(pattern, part):
    return re.fullmatch(".*".join(re.escape(piece) for piece in pattern.split("*")), part, re.DOTALL) is not None


def _match(patterns, parts):
    if not patterns:
        return not parts
    if patterns[0] == "**":
        return any(_match(patterns[1:], parts[index:]) for index in range(len(parts) + 1))
    return bool(parts) and _segment(patterns[0], parts[0]) and _match(patterns[1:], parts[1:])


def matches(pattern, path):
    """Whether a sensitive-path pattern matches a root-relative path, by the rules above."""
    return _match(pattern.split("/"), path.split("/"))


def _quote(path):
    """A path as an ASCII JSON string, so no file name can start a line of the gate's output or fail to print."""
    return json.dumps(path)


def _author_rule(record, author, owner):
    if author.lower() in (owner.lower(), record["agent_account"].lower()):
        return None
    return (
        "Author: %s is neither the repository owner %s nor the agent account %s, and outside PRs are re-landed. "
        "Fix: the agent account opens its own PR with the change, and this PR closes."
        % (author, owner, record["agent_account"])
    )


def _risk_rule(risk):
    if isinstance(risk, dict):
        return None
    problem = {
        "missing": "The body has no `Risk:` line",
        "more than one": "The body has more than one `Risk:` line",
        "malformed": "The `Risk:` line is malformed",
    }[risk]
    return (
        "Risk line: %s. Fix: keep exactly one line `Risk: <low|medium|high> — <reason>`, "
        "with an em dash and a reason." % problem
    )


def _revert_rule(repo, reverts, default_head, base, head):
    """(failure line or None, whether the PR is a pure revert)."""
    if reverts is None:
        return None, False
    fix = "Fix: name the squash commit or delete the line."
    if not isinstance(reverts, dict):
        problem = "more than one `Reverts:` line" if reverts == "more than one" else "a malformed `Reverts:` line"
        return "Pure revert: the body has %s; it takes one full commit SHA. %s" % (problem, fix), False
    sha = reverts["sha"]
    on_default = _is_commit(repo, sha) and _git(
        repo, ["merge-base", "--is-ancestor", sha, default_head], codes=(0, 1)
    )[0] == 0
    if not on_default:
        return "Pure revert: `Reverts: %s` names no commit on the default branch. %s" % (sha, fix), False
    if len(_line(repo, ["rev-list", "--parents", "-n", "1", sha]).split()) != 2:
        return None, False
    code, out = _git(repo, ["merge-tree", "--write-tree", "--merge-base=" + sha, base, sha + "^"], codes=(0, 1))
    if code != 0:
        return None, False
    recomputed = out.decode("utf-8").split("\n")[0].strip()
    return None, recomputed == _line(repo, ["rev-parse", head + "^{tree}"])


def changed_paths(repo, base, head):
    """Every path the PR changes from its merge-base, deletions and both sides of a rename included."""
    out = _git(repo, ["diff", "--no-ext-diff", "--no-textconv", "--no-renames", "--name-only", "-z", base, head])[1]
    return [path for path in out.decode("utf-8", "surrogateescape").split("\0") if path]


def _floor_rule(record, tier, paths):
    sensitive = record["sensitive_paths"] + record["confirmed"]["sensitive_paths"]
    floor, reaching = None, []
    for path in paths:
        here = [entry["floor"] for entry in sensitive if matches(entry["pattern"], path)]
        if not here:
            continue
        highest = max(here, key=RANK.get)
        if floor is None or RANK[highest] > RANK[floor]:
            floor, reaching = highest, [path]
        elif highest == floor:
            reaching.append(path)
    if floor is None or RANK[tier] >= RANK[floor]:
        return None
    named = ", ".join(_quote(path) for path in reaching[:SHOWN])
    if len(reaching) > SHOWN:
        named += " and %d more" % (len(reaching) - SHOWN)
    return (
        "Floors: the PR declares %s, and these changed paths have a %s floor: %s. "
        "Fix: declare `Risk: %s — <reason>`; no tier goes below a floor." % (tier, floor, named, floor)
    )


def verdict(repo, author, owner, body, default_head, head):
    """The gate's verdict on a PR: {"passed": bool, "failures": [line], "pure_revert": bool}.

    repo is a git repository holding the default branch's history and the head's objects;
    default_head is the default branch's commit whose record judges; author and owner are
    GitHub logins; body is the PR body's text.
    """
    def failed(line):
        return {"passed": False, "failures": [line], "pure_revert": False}

    try:
        data = _git(repo, ["show", "%s:%s" % (default_head, RECORD)])[1]
    except GitError:
        return failed("Record: the default branch has no readable %s. Fix: restore it on the default branch." % RECORD)
    try:
        record = parse_record(data)
    except RecordError as error:
        return failed("Record: the default branch's %s doesn't parse: %s. Fix: repair it on the default branch." % (RECORD, error))
    try:
        if not _is_commit(repo, head):
            return failed("Git: the head %s isn't available to the gate. Fix: rerun the gate." % head)
        code, out = _git(repo, ["merge-base", default_head, head], codes=(0, 1))
        if code != 0:
            return failed("Git: the head shares no history with the default branch. Fix: branch from the default branch.")
        base = out.decode("utf-8").strip()
        parsed = parse_body(body or "")
        failures = [_author_rule(record, author, owner), _risk_rule(parsed["risk"])]
        reverts_failure, pure = _revert_rule(repo, parsed["reverts"], default_head, base, head)
        failures.append(reverts_failure)
        if isinstance(parsed["risk"], dict) and not pure:
            failures.append(_floor_rule(record, parsed["risk"]["tier"], changed_paths(repo, base, head)))
    except GitError as error:
        return failed("Git: %s. Fix: rerun the gate." % error)
    failures = [line for line in failures if line]
    return {"passed": not failures, "failures": failures, "pure_revert": pure}


# The entry the workflow runs.


def _fetch_environment():
    """Git's environment for the fetch: the token reaches git through a credential helper, never argv."""
    env = dict(os.environ)
    if env.get("GH_TOKEN"):
        env.update(
            {
                "GIT_TERMINAL_PROMPT": "0",
                "GIT_CONFIG_COUNT": "1",
                "GIT_CONFIG_KEY_0": "credential.helper",
                "GIT_CONFIG_VALUE_0": '!f() { echo username=x-access-token; echo "password=$GH_TOKEN"; }; f',
            }
        )
    return env


def _fetch(repo, sha):
    result = subprocess.run(
        ["git", "-C", repo, "fetch", "--no-tags", "--quiet", "origin", sha],
        env=_fetch_environment(),
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
    )
    return result.returncode == 0


def _post(repository, head, result):
    """Post the verdict as the check run `governance-gate` on the head; True when GitHub took it."""
    if result["passed"]:
        title = "Passed: a pure revert" if result["pure_revert"] else "Passed"
        summary = "Every gate rule passed."
    else:
        title = "Failed: %d rule%s" % (len(result["failures"]), "" if len(result["failures"]) == 1 else "s")
        summary = "\n".join("- " + line for line in result["failures"])
    payload = {
        "name": CHECK,
        "head_sha": head,
        "status": "completed",
        "conclusion": "success" if result["passed"] else "failure",
        "output": {"title": title, "summary": summary},
    }
    posted = subprocess.run(
        ["gh", "api", "--method", "POST", "repos/%s/check-runs" % repository, "--input", "-"],
        input=json.dumps(payload, sort_keys=True).encode("utf-8"),
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
    )
    return posted.returncode == 0


def main(argv=None):
    parser = argparse.ArgumentParser(description="The governance gate's verdict on the PR in GITHUB_EVENT_PATH.")
    parser.add_argument("--post-check", action="store_true", help="post the verdict as a check run on the head")
    args = parser.parse_args(argv)
    repo = os.getcwd()
    with open(os.environ["GITHUB_EVENT_PATH"], encoding="utf-8") as handle:
        event = json.load(handle)
    pull = event["pull_request"]
    head = pull["head"]["sha"]
    try:
        default_head = _line(repo, ["rev-parse", "HEAD"])
        judged = _is_commit(repo, head) or _fetch(repo, head)
    except GitError as error:
        default_head, judged = "an unreadable checkout", False
        print("FAIL Git: %s" % error)
    if judged:
        result = verdict(
            repo, pull["user"]["login"], event["repository"]["owner"]["login"], pull["body"], default_head, head
        )
    else:
        result = {
            "passed": False,
            "failures": ["Git: the head %s couldn't be fetched. Fix: rerun the gate." % head],
            "pure_revert": False,
        }
    print("governance-gate on %s, judged by the default branch at %s" % (head, default_head))
    for line in result["failures"]:
        print("FAIL " + line)
    if result["passed"]:
        print("PASS " + ("a pure revert" if result["pure_revert"] else "every rule"))
    if args.post_check and not _post(os.environ["GITHUB_REPOSITORY"], head, result):
        print("FAIL posting the check run %s on %s" % (CHECK, head))
        return 1
    return 0 if result["passed"] else 1


if __name__ == "__main__":
    sys.dont_write_bytecode = True
    sys.exit(main())
